# DK NYM.  Nykøbing Mors
#
let ny = path("d3.dk.nym");

with detail = 4, railway = :first :pax :removed {
    with link = "point.dk.Nykøbing-Mors", railway = :station {
        track(ny[:nyf, :nym.f]);
        marker(:right :de.bf, ny[:nyk]);
        station(:top, ny[:nyk] >> 0.5mt >> 1sh >> 0.3dt,
            span(:bold, "Nykøbing Mors"), "NYM: –"
        );
    }
}

